import {petPresentationStyle} from './pet-presentation.mjs';
import {dawnPortraitStyle,dawnSkillStyle} from './dawnlion-art.mjs';
import {archiveFrame} from './archive-ui-art.mjs';
import {artifactIconStyle,artifactIconMarkup} from './campaign-artifact-art.mjs';
import growthMeta from '../assets/pets/growth-meta-v2.json' with {type:'json'};
import {artifactLevel,artifactUpgradeCost,upgradeArtifact,mirrorRules,ARTIFACTS,equippedArtifact,equipArtifact,artifactBonuses,swordRules,wardRules,springRules} from './campaign-artifacts.mjs';
import {selectCompanion,COMPANION_STATS,deployCompanion} from './campaign-companion.mjs';
import {PETS,PET_IDS,mirrorUnlocked,petRecord,petExperience,petStats,PET_SKILLS,evolvePet,petEvolutionCost,petStageLabel,petSkillLevel,petSkillPower,petSkillUpgradeRecipe,petSkillStoneCount,upgradePetSkill} from './campaign-pet-data.mjs';
export function petArtStyle(m,index){const r=m.frames[index]?.rect;if(!r)return '';const [w,h]=m.size;return `background-image:url('assets/pets/${m.file}');background-size:${w/r[2]*100}% ${h/r[3]*100}%;background-position:${r[0]/Math.max(1,w-r[2])*100}% ${r[1]/Math.max(1,h-r[3])*100}%;aspect-ratio:${r[2]}/${r[3]}`;}
export const petIcon=(id,form=0)=>petPortraitStyle(id,form);
export function petPortraitStyle(id,form=0){const renewed=form===0&&petPresentationStyle(id,0,{portrait:true});if(renewed)return renewed;if(id==='dawnlion')return dawnPortraitStyle(form);const m=growthMeta.portraits,f=m.frames.find(f=>f.pet===id&&f.form===Math.max(0,Math.min(2,form))),r=f?.rect;if(!r)return '';const side=Math.min(m.size[0],m.size[1],Math.max(r[2],r[3])*1.06),x=Math.max(0,Math.min(m.size[0]-side,r[0]+r[2]/2-side/2)),y=Math.max(0,Math.min(m.size[1]-side,r[1]+r[3]/2-side/2));return `background-image:url('assets/pets/${m.file}');background-size:${m.size[0]/side*100}% ${m.size[1]/side*100}%;background-position:${x/Math.max(1,m.size[0]-side)*100}% ${y/Math.max(1,m.size[1]-side)*100}%;aspect-ratio:1`;}
export const petSkillStyle=(id,index)=>petPresentationStyle(id,index)||(id==='dawnlion'?dawnSkillStyle(index):petArtStyle(growthMeta.icons,PETS[id].row*3+index));
function petSkillCard(record,skill,index,profile){
 const locked=index>record.form,recipe=petSkillUpgradeRecipe(record,index),level=petSkillLevel(record,index),power=petSkillPower(record,index),stones=petSkillStoneCount(profile);
 const price=recipe?`${recipe.coins}金币${recipe.stoneCount?' · 技能石×'+recipe.stoneCount+'（持有'+stones+'）':''}`:'';
 const cost=recipe?`<div class="pet-skill-cost" aria-label="${price}"><span class="pet-cost-coins"><svg viewBox="12 220 1230 854" aria-hidden="true"><image href="assets/campaign-results/treasure-coins-v1.png" width="1254" height="1254"/></svg><b>${recipe.coins}</b><span>金币</span></span>${recipe.stoneCount?`<span class="pet-cost-stones ${stones<recipe.stoneCount?'missing':''}"><img src="assets/items/pet-skill-stone-v1.png" alt=""><b>×${recipe.stoneCount}</b><span>技能石</span><em>${stones<recipe.stoneCount?'缺'+(recipe.stoneCount-stones):'持有'+stones}</em></span>`:''}</div>`:'';
 return `<article class="has-tip ${locked?'locked':''}" data-tip="${skill.name}：${skill.text} 消耗${skill.cost}法力，冷却${skill.cd}秒。每次升级另加灵宠4%基础生命与2.5%基础攻击。"><i style="${petSkillStyle(record.kind,index)}"></i><div><strong>${skill.name} · Lv.${level} / 5</strong><small>${locked?'形态'+(index+1)+'解锁':skill.cost+'法力 · '+skill.cd+'秒 · 效果×'+power}</small><p>${skill.text}</p>${cost}<button class="archive-primary pet-skill-upgrade" data-pet-skill-upgrade="${record.id}" data-pet-skill-index="${index}" ${recipe?'':'disabled'}>${archiveFrame('upgrade')}<span>${locked?'尚未解锁':recipe?'升至 Lv.'+recipe.nextLevel:'已满级'}</span></button></div></article>`;
}
export function artifactPanel(p,ui={}){
 const id=ARTIFACTS[ui.artifactSelected]?ui.artifactSelected:equippedArtifact(p)||'mirror',d=ARTIFACTS[id],level=artifactLevel(p,id),open=level>0,cost=artifactUpgradeCost(p,id),equipped=equippedArtifact(p)===id;
 // SVG view boxes match the existing measured sprite crops; mobile can fit the whole relic without stretching.
 const mobilePortrait=id==='mirror'?'<svg class="artifact-mobile-portrait" viewBox="102 14 626 953" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><svg x="102" y="14" width="626" height="953" viewBox="102 14 626 953" overflow="hidden"><image href="assets/pets/mirror-v1.png" width="1536" height="1024"/></svg></svg>':id==='sword'?'<svg class="artifact-mobile-portrait" viewBox="79 39 440 431" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><svg x="79" y="39" width="440" height="431" viewBox="79 39 440 431" overflow="hidden"><image href="assets/artifacts/sword-v1.png" width="1536" height="1024"/></svg></svg>':'';
 let rows=[],help=d.description;
 if(id==='mirror'){const r=mirrorRules(p);rows=[['装备生命加成','+'+(20+Math.max(0,level-1)*5)],['捕捉距离',r.range],['满血捕捉率',Math.round((.12+r.chanceBonus)*100)+'%'],['低血捕捉上限',Math.round(Math.min(.95,.9+r.chanceBonus)*100)+'%'],['冷却',r.cooldown.toFixed(2)+'秒']];}
 if(id==='sword'){const r=swordRules(p);rows=[['装备攻击加成','+'+(3+Math.max(0,level-1))],['单剑伤害',r.damage],['持续 / 冷却',r.duration+' / '+r.cooldown+'秒'],['法力消耗','启动'+r.startMana+' · 每秒'+r.manaPerSecond]];}
 if(id==='ward'){const r=wardRules(p);rows=[['免疫伤害',r.immunity.toFixed(2)+'秒'],['攻击速度','+50%'],['攻速持续',r.hasteDuration.toFixed(2)+'秒'],['冷却',r.cooldown+'秒']];}
 if(id==='spring'){const r=springRules(p);rows=[['生命恢复',Math.round(r.healthRatio*100)+'%上限'],['法力恢复',Math.round(r.manaRatio*100)+'%上限'],['冷却',r.cooldown+'秒']];}
 return `<div class="artifact-choices">${Object.entries(ARTIFACTS).map(([key,v])=>`<button data-artifact-select="${key}" class="${id===key?'selected':''}"><i class="artifact-art ${key}" style="${artifactIconStyle(key)}">${artifactIconMarkup(key)}</i><span><b>${v.name}</b><small>${artifactLevel(p,key)?'Lv.'+artifactLevel(p,key):petStageLabel(v.stage)+'掉落'}${equippedArtifact(p)===key?' · 已装备':''}</small></span></button>`).join('')}</div><div class="mirror-layout"><section class="mirror-display"><i class="artifact-large artifact-art ${id}" style="${artifactIconStyle(id)}">${artifactIconMarkup(id)}${mobilePortrait}</i><small>RELIC OF THE REALM</small><h3>${d.name} ${open?'Lv.'+level:''}</h3><p>${d.subtitle}</p></section><section class="mirror-description"><div class="artifact-detail-scroll" tabindex="0" aria-label="法器属性与介绍"><h3>${open?equipped?'当前装备中':'已拥有 · 尚未装备':'尚未获得'}</h3><p>${open?help:petStageLabel(d.stage)+'首领掉落，靠近按C拾取。'}</p><dl>${rows.map(([name,value])=>`<dt>${name}</dt><dd>${value}</dd>`).join('')}</dl></div><div class="artifact-action-bar"><button class="archive-primary" data-artifact-equip="${id}" ${open?'':'disabled'}>${archiveFrame('upgrade')}<span>${equipped?'卸下':'装备'}${d.name}</span></button><div class="artifact-upgrade"><strong>${open?'法宝等级 '+level+' / '+d.maxLevel:'拾取后开放金币升级'}</strong><button class="archive-primary" data-artifact-upgrade="${id}" ${cost===null?'disabled':''}>${archiveFrame('upgrade')}<span>${cost===null?open?'已满级':'尚未获得':'升级法宝 · '+cost+'金币'}</span></button></div></div></section></div>`;
}
export function petPanel(ui,p){const pets=petRecord(p),selected=pets.find(v=>v.id===ui.petSelected)||pets.find(v=>v.id===p.activePetId)||pets[0],d=selected&&PETS[selected.kind],stats=selected&&petStats(selected),xp=selected&&petExperience(selected.exp||0),vitals=selected&&(ui.getWorld()?.campaign.companionStates?.[selected.id]||selected.vitals),nextForm=selected?(selected.form||0)+1:0,canEvolve=selected&&selected.form<2&&xp.level>=(selected.form===0?5:10);return `<div class="pet-archive"><section><div class="section-title"><h3>灵宠背包</h3><small>已收伏 ${pets.length} 只 · 最多一只出战</small></div><div class="pet-bag-grid">${pets.map(v=>`<button class="pet-owned ${v.id===selected?.id?'selected':''}" data-pet-select="${v.id}" aria-label="查看${PETS[v.kind].name}"><i style="${petIcon(v.kind,v.form)}"></i>${p.activePetId===v.id?'<em class="pet-active-badge">出战中</em>':''}<strong>${PETS[v.kind].name}</strong><small>Lv.${petExperience(v.exp||0).level} · 形态 ${v.form+1} · ${PETS[v.kind].forms[v.form]}</small></button>`).join('')||'<div class="pet-empty"><h3>尚未收伏灵宠</h3><p>通关第一章第5、9关与第二章第3、6关后，在关卡详情进入宠物副本。击败首领后，新的灵兽会出现。</p><p>装备收妖镜，降低灵宠生命后按 V 捕捉。</p></div>'}</div><div class="pet-places">${PET_IDS.map(id=>`<div><i style="${petIcon(id)}"></i><span>${petStageLabel(PETS[id].stage)} · ${PETS[id].name}<small>通关本关后解锁专属副本</small></span></div>`).join('')}</div></section><aside class="pet-description">${d?`<i class="pet-portrait" style="${petIcon(d.id,selected.form)}"></i><h3>${d.name}</h3><button class="pet-deploy-button" data-pet-deploy="${selected.id}" aria-pressed="${p.activePetId===selected.id}" >${archiveFrame('upgrade')}<span>${p.activePetId===selected.id?'收回灵宠':'派出灵宠'}</span><small>${p.activePetId===selected.id?'出战中':'待命'}</small></button><p class="pet-deploy-note">${ui.getWorld()?'回收再出战保持本关生命、法力；一次只可上场一只。':p.activePetId===selected.id?'下一次进入关卡时，它会自动出现在身边。':'选择一只已捕获灵宠，陪同下一次关卡。'}</p><p>${d.description}</p><dl><dt>等级 / 经验</dt><dd>Lv.${xp.level} · ${xp.xp}/${xp.next}</dd><dt>生命</dt><dd>${Math.ceil(vitals?.hp??stats.maxHp)} / ${stats.maxHp}</dd><dt>法力</dt><dd>${Math.floor(vitals?.mp??stats.maxMp)} / ${stats.maxMp}</dd><dt>攻击力</dt><dd>${stats.damage}</dd><dt>捕获个体差异</dt><dd>生命${Math.round(((selected.traits?.hp??1)-1)*100)}% / 法力${Math.round(((selected.traits?.mp??1)-1)*100)}% / 攻击${Math.round(((selected.traits?.attack??1)-1)*100)}%</dd><dt>当前形态</dt><dd>${d.forms[selected.form]}</dd><dt>捕捉地点</dt><dd>${petStageLabel(selected.capturedStage)} · 宠物副本</dd><dt>伴战方式</dt><dd>${COMPANION_STATS[d.id].ranged?'灵弹支援':'近身扑爪'}</dd></dl><div class="pet-skill-cards">${PET_SKILLS[d.id].map((skill,i)=>petSkillCard(selected,skill,i,p)).join('')}</div><button class="pet-evolve-button" data-pet-evolve="${selected.id}" ${!canEvolve||ui.getWorld()?'disabled':''}>${selected.form>=2?'已达最终形态':canEvolve?'进化为 · '+d.forms[nextForm]+' · '+petEvolutionCost(selected)+'金币':'灵宠'+(selected.form===0?5:10)+'级可进化'}</button><p class="pet-deploy-note">出战时小怪每只5宠物经验、首领25；5级和10级在出战整备页手动进化，各多解锁一招。</p><div class="pet-form-line">${d.forms.map((n,i)=>`<span class="${i===selected.form?'active':''}"><b>0${i+1}</b>${n}</span>`).join('')}</div><p class="system-note">出战后自动跟随、跳上台面并协助攻击；同一次关卡内回收、换宠再放出保留生命和法力；重新进入关卡恢复满血满蓝。捕捉阶段自动停手。技能自动施放并消耗独立法力，法力不足时使用普通攻击。</p>`:'<i class="mirror-icon"></i><h3>循灵而行</h3><p>选择已捕获的灵宠，查看它的来历与形态。</p>'}</aside></div>`;}
export function handlePetUI(ui,b){if(b.dataset.petSkillUpgrade){ui.mutate(()=>upgradePetSkill(ui.getProfile(),b.dataset.petSkillUpgrade,Number(b.dataset.petSkillIndex)));return true;}if(b.dataset.artifactSelect){ui.artifactSelected=b.dataset.artifactSelect;ui.render();return true;}if(b.dataset.artifactEquip){ui.mutate(()=>{const p=ui.getProfile(),id=equippedArtifact(p)===b.dataset.artifactEquip?null:b.dataset.artifactEquip,w=ui.getWorld();if(w)w.campaign.noStatHealOnce=true;return equipArtifact(p,id);});return true;}if(b.dataset.artifactUpgrade){ui.mutate(()=>{const result=upgradeArtifact(ui.getProfile(),b.dataset.artifactUpgrade),w=ui.getWorld();if(w)w.campaign.noStatHealOnce=true;return result;});return true;}if(b.dataset.petEvolve){ui.mutate(()=>{if(ui.getWorld())throw Error('请在世界地图进化灵宠');return evolvePet(ui.getProfile(),b.dataset.petEvolve);});return true;}if(b.dataset.petDeploy){ui.mutate(()=>{const p=ui.getProfile(),id=p.activePetId===b.dataset.petDeploy?null:b.dataset.petDeploy;return ui.getWorld()?deployCompanion(ui.getWorld(),id):selectCompanion(p,id);});return true;}if(b.dataset.petSelect){ui.petSelected=b.dataset.petSelect;ui.render();return true;}if(b.hasAttribute('data-mirror-equip')){ui.mutate(()=>{const p=ui.getProfile();if(!mirrorUnlocked(p))throw Error('击败第4关首领后按C拾取收妖镜');const w=ui.getWorld();if(w)w.campaign.noStatHealOnce=true;return equipArtifact(p,equippedArtifact(p)==='mirror'?null:'mirror');});return true;}return false;}
